object HabakkukData {
    val verses: List<Verse> = listOf(
        Verse(book = "Abakouk", chapter = 1, verseNumber = 1, text = "Men mesaj Bondye te bay pwofèt Abakouk nan yon vizyon.", bookId = 35),
        Verse(book = "Abakouk", chapter = 1, verseNumber = 2, text = "Seyè! Konbe tan ankò pou m' pase ap rele ou, ap mande ou sekou anvan pou ou tande m'? Konbe tan ankò pou m' pase ap rele nan zòrèy ou anvan pou ou vin delivre nou anba moun k'ap maltrete nou yo?", bookId = 35),
        Verse(book = "Abakouk", chapter = 1, verseNumber = 3, text = "Poukisa w'ap fè m' wè tout mechanste sa yo? Ki jan ou ka rete kanpe konsa ap gade tout lenjistis sa yo? Se piyay ak mechanste ase ki devan je m'! Toupatou se goumen, se kont.", bookId = 35),
        Verse(book = "Abakouk", chapter = 1, verseNumber = 4, text = "Lalwa a la, li pa sèvi anyen. Ou pa ka jwenn jistis. Mechan yo ap kraze moun k'ap mache dwat. Lajistis devan dèyè.", bookId = 35),
        Verse(book = "Abakouk", chapter = 1, verseNumber = 5, text = "Seyè a pale ak pèp li a, li di: -Voye je nou gade nasyon ki bò kote nou yo. Nou pral sezi, nou pral tranble. Mwen pral fè yon travay devan je nou. Si se moun ki ta vin di nou sa, nou pa ta kwè.", bookId = 35),
        Verse(book = "Abakouk", chapter = 1, verseNumber = 6, text = "M'ap fè moun peyi Kalde yo kanpe. Se yon pèp ki san pitye, ki san manman. Y'ap mache toupatou sou latè, y'ap pran peyi lòt pèp nan men yo.", bookId = 35),
        Verse(book = "Abakouk", chapter = 1, verseNumber = 7, text = "Kote yo pase, yo fè moun pè yo. Yo pa nan jwèt ak pesonn. Yo pa pran lòd nan men pesonn. Yo fè sa yo pi pito.", bookId = 35),
        Verse(book = "Abakouk", chapter = 1, verseNumber = 8, text = "Chwal yo kouri pi rèd pase chat mawon. Yo pi move pase chen mawon ki grangou. Kavalye yo soti byen lwen, y'ap kouri vini. Yo tankou malfini k'ap plonje sou poul.", bookId = 35),
        Verse(book = "Abakouk", chapter = 1, verseNumber = 9, text = "Sòlda yo ap vini pou fè piyay. Tout moun pè lè yo wè yo ap pwoche, paske yo ranmase prizonye an kantite, san gad dèyè.", bookId = 35),
        Verse(book = "Abakouk", chapter = 1, verseNumber = 10, text = "Y'ap pase wa yo nan betiz. Y'ap pase chèf yo nan rizib. Pa gen fò ki ka rete yo. Yo annik anpile tè bò miray yo, lèfini yo moute pran yo.", bookId = 35),
        Verse(book = "Abakouk", chapter = 1, verseNumber = 11, text = "Yo pase tankou yon koutvan, yo kraze brize, epi y' al fè wout yo. Bondye yo se fòs yo gen nan ponyèt yo. Se nan sa yo kwè.", bookId = 35),
        Verse(book = "Abakouk", chapter = 1, verseNumber = 12, text = "Seyè! Depi tout tan se ou ki Bondye. Ou se Bondye m', Bondye tout bon ki la pou tout tan an. Seyè, Bondye mwen, ou menm k'ap pwoteje m'! Se pèp sa a ou chwazi pou fè travay ou? Se pèp sa a ou voye pou pini nou?", bookId = 35),
        Verse(book = "Abakouk", chapter = 1, verseNumber = 13, text = "Ou twò bon pou ou kite moun ap fè mechanste devan je ou konsa! Ou pa ka rete ap gade moun ap fè lenjistis devan ou konsa! Ki jan ou fè rete ap gade bann moun trèt sa yo? Poukisa ou pa di anyen lè mechan yo ap fini ak moun ki pi inonsan pase yo?", bookId = 35),
        Verse(book = "Abakouk", chapter = 1, verseNumber = 14, text = "Kouman ou ka aji ak moun tankou si yo te pwason nan lanmè, tankou koulèv nan raje ki pa gen mèt?", bookId = 35),
        Verse(book = "Abakouk", chapter = 1, verseNumber = 15, text = "Moun Babilòn yo pran moun nan zen tankou pwason. Yo rale yo nan senn, yo ranmase yo nan nas. Lèfini, yo kontan, y'ap fè fèt.", bookId = 35),
        Verse(book = "Abakouk", chapter = 1, verseNumber = 16, text = "Se sak fè tou, yo fè ofrann bèt yo touye pou senn yo, yo boule lansan pou nas yo, paske se nan senn yo ak nan nas yo yo jwenn tout kalite bon pwason pou yo manje.", bookId = 35),
        Verse(book = "Abakouk", chapter = 1, verseNumber = 17, text = "Eske yo pral toujou sèvi ak nepe yo san rete, pou yo touye moun lòt nasyon san yo pa gen pitye pou yo?", bookId = 35),
        Verse(book = "Abakouk", chapter = 2, verseNumber = 1, text = "Mwen moute sou fò a pou m' veye. Mwen kanpe sou tèt miray ranpa a, m'ap tann pou m' wè sa Seyè a pral di m', ki repons li pral ban mwen apre tout plenyen mwen plenyen ba li a.", bookId = 35),
        Verse(book = "Abakouk", chapter = 2, verseNumber = 2, text = "Men repons Seyè a ban mwen. Li di m' konsa: -Ekri sa mwen pral fè ou wè a. Grave l' byen grave sou wòch plat pou moun ka li l' fasil.", bookId = 35),
        Verse(book = "Abakouk", chapter = 2, verseNumber = 3, text = "Ekri l' paske se poko lè pou sa m' pral fè ou wè a rive. Men, li p'ap pran lontan ankò pou l' rive. Li gen pou l' rive vre. Si li pran reta pou l' rive, ou mèt tann. Paske, wè pa wè, li gen pou l' rive lè pou l' rive a.", bookId = 35),
        Verse(book = "Abakouk", chapter = 2, verseNumber = 4, text = "Men mesaj la: Moun ki pa mache dwat devan Bondye p'ap chape. Men moun ki mache dwat yo va viv paske yo te kenbe konfyans fèm yo nan Bondye.", bookId = 35),
        Verse(book = "Abakouk", chapter = 2, verseNumber = 5, text = "Richès fè moun pèdi tèt yo pi mal pase bweson. Moun ki gen lògèy pa ka rete trankil. Tankou simityè, yo pa janm gen ase. Tankou kote mò yo ye a, yo pa janm gen kont yo. Yo mache pran tout nasyon yo pou yo. Yo mete tout pèp yo anba ponyèt yo.", bookId = 35),
        Verse(book = "Abakouk", chapter = 2, verseNumber = 6, text = "Men, tout pèp sa yo pral pase yo nan betiz, yo pral rele chalbari dèyè yo, yo pral bay istwa sou yo. Yo pral di: Madichon pou moun k'ap plede pran sa ki pa pou yo! Kilè y'a sispann fè sa? Madichon pou moun k'ap bay ponya epi k'ap fè moun peye gwo enterè mete sou li!", bookId = 35),
        Verse(book = "Abakouk", chapter = 2, verseNumber = 7, text = "Talè konsa, se nou ki pral nan pran ponya. Moun nou dwe yo pral leve dèyè nou. Yo pral piye tou sa nou genyen.", bookId = 35),
        Verse(book = "Abakouk", chapter = 2, verseNumber = 8, text = "Nou te piye anpil nasyon. Koulye a rès moun ki te chape yo pral piye tou sa nou genyen paske nou te touye anpil moun, nou te fè peyi yo, lavil yo ansanm ak moun ki te rete ladan yo pase anpil mati anba men nou.", bookId = 35),
        Verse(book = "Abakouk", chapter = 2, verseNumber = 9, text = "Madichon pou moun k'ap vòlò pou fè fanmi yo rich, k'ap bati kay sou mòn pou malè pa rive yo!", bookId = 35),
        Verse(book = "Abakouk", chapter = 2, verseNumber = 10, text = "Se wont nou fè fanmi nou yo wont. Lè nou detwi anpil nasyon konsa, se pwòp tèt nou nou fè mal.", bookId = 35),
        Verse(book = "Abakouk", chapter = 2, verseNumber = 11, text = "Ata wòch ki nan miray yo ap denonse nou. Poto travès kay yo ap fè menm bagay la tou.", bookId = 35),
        Verse(book = "Abakouk", chapter = 2, verseNumber = 12, text = "Madichon pou moun k'ap touye moun, k'ap fè lenjistis pou bati lavil yo!", bookId = 35),
        Verse(book = "Abakouk", chapter = 2, verseNumber = 13, text = "Travay pèp yo ap fè a pral boule nan dife. Se pou gremesi nasyon yo ap fatige kò yo travay di. Se Seyè a menm k'ap fè sa rive konsa.", bookId = 35),
        Verse(book = "Abakouk", chapter = 2, verseNumber = 14, text = "Menm jan lanmè a plen dlo, se konsa toupatou sou latè moun pral konnen pouvwa Bondye a.", bookId = 35),
        Verse(book = "Abakouk", chapter = 2, verseNumber = 15, text = "Madichon pou moun k'ap fè moun parèy yo bwè pou avili yo. Yo vide bweson ba yo jouk yo sou. Yo mete yo toutouni devan tout moun.", bookId = 35),
        Verse(book = "Abakouk", chapter = 2, verseNumber = 16, text = "Moun p'ap fè lwanj pou yo. Okontrè, yo pral trennen yo nan labou. Se yo menm ki pral bwè pou yo sou jouk y'a mete yo toutouni devan tout moun tou. Seyè a nan kòlè li pral fè yo bwè gode chatiman li pare pou yo a. Yo t'ap chache lwanj? Se wont y'a wont pito.", bookId = 35),
        Verse(book = "Abakouk", chapter = 2, verseNumber = 17, text = "Yo te koupe tout gwo rakbwa peyi Liban an. Koulye a, se yo yo pral koupe voye jete. Yo te touye tout bèt li yo. Koulye a, bèt li yo pral fè yo kouri al kache. Tou sa pral rive yo paske yo te touye anpil moun, yo te fè peyi yo, lavil yo ansanm ak moun ladan yo pase anpil mati anba men yo.", bookId = 35),
        Verse(book = "Abakouk", chapter = 2, verseNumber = 18, text = "Kisa yon estati an bwa ka fè pou nou, pou nou fè moun travay fè li pou nou? Kisa yon estati fèt ak metal yo fonn ka fè pou nou? Se manti ase l'ap ban nou. Sa sa ap rapòte nou lè nou fè zidòl ki pa ka pale pou nou mete konfyans nou nan yo?", bookId = 35),
        Verse(book = "Abakouk", chapter = 2, verseNumber = 19, text = "Madichon pou moun k'ap pale ak yon bout bwa, epi k'ap di l': Leve non! Madichon pou moun k'ap pale ak yon moso wòch ki pa gen lapawòl, epi k'ap di l': Kanpe non! Eske bout bwa ak moso ròch ka di ou anyen? Ou kouvri yo avèk plak lò ak plak ajan, se vre. Men yo pa gen lavi.", bookId = 35),
        Verse(book = "Abakouk", chapter = 2, verseNumber = 20, text = "Seyè a kanpe nan kay ki apa pou li a. Se pou tout moun sou latè pe bouch devan li.", bookId = 35),
        Verse(book = "Abakouk", chapter = 3, verseNumber = 1, text = "Men lapriyè pwofèt Abakouk te fè pou li plenyen sò li bay Bondye.", bookId = 35),
        Verse(book = "Abakouk", chapter = 3, verseNumber = 2, text = "-Seyè! Mwen tande tou sa ou te di. M' sezi, m'ap tranble nan tout kò m'. Seyè, gwo mèvèy ou te konn fè nan tan lontan yo, koulye a, fè nou wè yo nan lanne k'ap vini yo. Menm lè ou fache, pa bliye gen pitye pou nou!", bookId = 35),
        Verse(book = "Abakouk", chapter = 3, verseNumber = 3, text = "Bondye ap vini soti peyi Edon. Bondye tout bon an ap desann soti sou mòn Paran an. Pouvwa li kouvri tout syèl la. Lwanj li toupatou sou latè.", bookId = 35),
        Verse(book = "Abakouk", chapter = 3, verseNumber = 4, text = "Li klere kou gwo solèy. Zèklè ap soti nan men l'. Se la li kache tout pouvwa li.", bookId = 35),
        Verse(book = "Abakouk", chapter = 3, verseNumber = 5, text = "Li voye vye maladi pran devan li. Li mete lanmò mache dèyè l'.", bookId = 35),
        Verse(book = "Abakouk", chapter = 3, verseNumber = 6, text = "Lè l' kanpe, latè pran tranble. Li annik gade, moun tout nasyon gen kè kase. Mòn ki la depi lontan yo kraze an miyèt moso. Ti mòn tan lontan yo vin plat. Chemen kote li te konn pase tan lontan yo louvri devan l'.", bookId = 35),
        Verse(book = "Abakouk", chapter = 3, verseNumber = 7, text = "Mwen wè moun peyi Letiopi yo nan gwo lafliksyon. Moun peyi Madyan yo tou pè.", bookId = 35),
        Verse(book = "Abakouk", chapter = 3, verseNumber = 8, text = "Eske se sou gwo rivyè yo ou move konsa, Seyè? Eske se sou lanmè a ou fache? Eske se sou lanmè a ou ankòlè konsa, kifè ou moute sou nwaj yo tankou sou chwal ou, tankou sou cha ou pou al delivre pèp ou a?", bookId = 35),
        Verse(book = "Abakouk", chapter = 3, verseNumber = 9, text = "Ou kenbe banza ou tou pare nan men ou. Pawòl ou se pakèt flèch anpwazonnen. Zèklè ou yo fann tè a louvri.", bookId = 35),
        Verse(book = "Abakouk", chapter = 3, verseNumber = 10, text = "Mòn yo wè ou, yo pran tranble. Gwo lapli ap tonbe soti nan syèl la. Dlo anba tè yo ap gwonde. Gwo lanm lanmè ap leve byen wo.", bookId = 35),
        Verse(book = "Abakouk", chapter = 3, verseNumber = 11, text = "Flèch ou yo pati tankou zèklè. Lans ou yo klere byen klere. Lalin ak solèy pa parèt tèt yo deyò.", bookId = 35),
        Verse(book = "Abakouk", chapter = 3, verseNumber = 12, text = "Ou move, w'ap mache toupatou sou latè. Nan kòlè ou, ou pilonnen nasyon yo anba pye ou.", bookId = 35),
        Verse(book = "Abakouk", chapter = 3, verseNumber = 13, text = "Ou soti pou delivre pèp ou a, pou sove wa ou chwazi a. Ou kraze chèf mechan yo. Ou detwi tout moun li yo nèt.", bookId = 35),
        Verse(book = "Abakouk", chapter = 3, verseNumber = 14, text = "Avèk flèch ou yo, ou pèse kòmandan an chèf lame yo a, lè yo t'ap vare sou nou tankou yon van tanpèt pou gaye nou. Je yo gran louvri ak kontantman tankou moun ki pral devore pòv malere yo kote yo kache a.", bookId = 35),
        Verse(book = "Abakouk", chapter = 3, verseNumber = 15, text = "Ou foule lanmè a anba pye chwal ou yo. Ou fè dlo lanmè a kimen.", bookId = 35),
        Verse(book = "Abakouk", chapter = 3, verseNumber = 16, text = "Mwen tande tou sa. Vant mwen bouyi! Lè m' tande tout bri sa yo, bouch mwen pran tranble. Tout zo nan kò m' ap fè m' mal. M' pa ka kanpe sou janm mwen ankò! Mwen rete byen trankil, m'ap tann jou malè a rive, jou Bondye pral mache pran moun k'ap chache nou kont yo.", bookId = 35),
        Verse(book = "Abakouk", chapter = 3, verseNumber = 17, text = "Pye fig frans yo te mèt pa donnen, pye rezen yo te mèt pa bay rezen, rekòt oliv yo te mèt pa bon, jaden yo te mèt pa bay manje, mouton yo te mèt mouri nan sèka yo, bèf yo te mèt mouri nan pak yo,", bookId = 35),
        Verse(book = "Abakouk", chapter = 3, verseNumber = 18, text = "mwen menm, m'ap toujou kontan poutèt Seyè a. M'ap fè fèt pou Bondye k'ap delivre m' lan.", bookId = 35),
        Verse(book = "Abakouk", chapter = 3, verseNumber = 19, text = "Se Seyè a ki tout fòs mwen. Li asire pye m' tankou pye kabrit. Li fè m' mache sou mòn yo, san m' pa tonbe. Pou chèf k'ap dirije moun k'ap chante yo.", bookId = 35)
    )
